//! The five-island EggWars arena: one larger central island and four outer islands on the
//! cardinal axes, all generated by `generate_island` into one global `VoxelGrid`.
//!
//! The layout is fixed and seed-independent: a seed changes each island's terrain, never where
//! the islands are, so later bridges and structures can rely on stable positions. Each island
//! draws its own seed from the global seed with a stateless hash keyed by its identity, so no
//! island depends on generation order or on any other island.

use std::{error::Error, fmt};

use super::{
    IslandBounds, IslandConfig, IslandError, IslandStats, generate_island,
    noise::{Domain, hash3},
};
use crate::voxel::{BlockType, VoxelGrid, VoxelGridError, VoxelPosition};

#[cfg(test)]
mod tests;

/// Footprint side length of the central island.
pub const CENTER_FOOTPRINT: u32 = 24;
/// Footprint side length of each outer island, the generator's standard 16×16.
pub const OUTER_FOOTPRINT: u32 = super::DEFAULT_FOOTPRINT;
/// The central island's underside reaches a little deeper than the outer islands'.
pub const CENTER_THICKNESS: u32 = 15;
pub const OUTER_THICKNESS: u32 = 12;
/// Shared grass level of all five islands, so future bridges can run level between them.
pub const SURFACE_LEVEL: i32 = 0;
/// Center-to-center distance from the central island to each outer island, in blocks.
///
/// With half extents of 12 and 8 this leaves a nominal 12-block gap between square footprints;
/// the round silhouettes widen the visible gap to roughly 12–17 blocks. That is long enough to
/// read as open void from the initial camera and short enough for a Minecraft-style bridge.
pub const ISLAND_SEPARATION: u32 = 32;
/// Empty cells required between the regions of any two islands, so no two islands can touch.
pub const MIN_ISLAND_GAP: u32 = 1;

/// Identity of one arena island. The discriminant is its index in `IslandId::ALL` and in every
/// per-island array of the arena.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum IslandId {
    Center,
    North,
    South,
    East,
    West,
}

impl IslandId {
    pub const ALL: [Self; 5] = [
        Self::Center,
        Self::North,
        Self::South,
        Self::East,
        Self::West,
    ];

    pub const fn is_center(self) -> bool {
        matches!(self, Self::Center)
    }

    /// Unit step `(dx, dz)` from the arena center toward this island: north is `-Z`, south `+Z`,
    /// east `+X`, west `-X`; `(0, 0)` for the center. Its negation points from an outer island
    /// toward the center, the direction a bridge would take.
    pub const fn direction(self) -> (i32, i32) {
        match self {
            Self::Center => (0, 0),
            Self::North => (0, -1),
            Self::South => (0, 1),
            Self::East => (1, 0),
            Self::West => (-1, 0),
        }
    }

    pub const fn name(self) -> &'static str {
        match self {
            Self::Center => "Center",
            Self::North => "North",
            Self::South => "South",
            Self::East => "East",
            Self::West => "West",
        }
    }

    /// Stable salt for this island's seed. Tags, not array positions, so reordering `ALL` or
    /// adding an island never changes another island's terrain.
    const fn seed_domain(self) -> Domain {
        Domain::from_tag(match self {
            Self::Center => *b"arn-cntr",
            Self::North => *b"arn-nrth",
            Self::South => *b"arn-soth",
            Self::East => *b"arn-east",
            Self::West => *b"arn-west",
        })
    }
}

/// The generator seed of one island, a pure function of the global seed and the island.
pub const fn island_seed(global_seed: u64, island: IslandId) -> u64 {
    hash3(global_seed, island.seed_domain(), 0, 0, 0)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArenaError {
    /// One island's own configuration is invalid (for example its region leaves `i32`).
    Island {
        island: IslandId,
        error: IslandError,
    },
    /// Two islands' regions overlap or lie closer than `MIN_ISLAND_GAP`.
    Overlap { first: IslandId, second: IslandId },
    /// The global grid enclosing the arena could not be created.
    Grid(VoxelGridError),
    /// Requested grid bounds do not contain every island region.
    GridTooSmall,
}

impl fmt::Display for ArenaError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Island { island, error } => {
                write!(formatter, "{} island: {error}", island.name())
            }
            Self::Overlap { first, second } => write!(
                formatter,
                "{} and {} island regions overlap or touch",
                first.name(),
                second.name()
            ),
            Self::Grid(error) => write!(formatter, "arena grid: {error}"),
            Self::GridTooSmall => formatter.write_str("arena grid does not contain every island"),
        }
    }
}

impl Error for ArenaError {}

/// A validated placement of the five islands. Constructing one checks every island config and
/// every pair of regions, so generation never starts on a layout it would have to abandon.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ArenaLayout {
    separation: u32,
    /// Indexed by `IslandId as usize`.
    islands: [IslandConfig; 5],
    bounds: IslandBounds,
}

impl ArenaLayout {
    /// The project's arena: `ISLAND_SEPARATION` between the center and each outer island.
    pub fn eggwars() -> Self {
        Self::new(ISLAND_SEPARATION).expect("the EggWars arena layout must be valid")
    }

    /// The cross-shaped layout with `separation` blocks from the central island's center to each
    /// outer island's center, all at `SURFACE_LEVEL`.
    pub fn new(separation: u32) -> Result<Self, ArenaError> {
        let islands = per_island(|id| island_config(id, separation))?;
        let regions = per_island(|id| {
            islands[id as usize]
                .bounds()
                .map_err(|error| ArenaError::Island { island: id, error })
        })?;
        for (a, &first) in IslandId::ALL.iter().enumerate() {
            for &second in &IslandId::ALL[a + 1..] {
                if too_close(regions[first as usize], regions[second as usize]) {
                    return Err(ArenaError::Overlap { first, second });
                }
            }
        }

        let bounds = regions[1..]
            .iter()
            .fold(regions[0], |all, region| IslandBounds {
                min: VoxelPosition::new(
                    all.min.x.min(region.min.x),
                    all.min.y.min(region.min.y),
                    all.min.z.min(region.min.z),
                ),
                max: VoxelPosition::new(
                    all.max.x.max(region.max.x),
                    all.max.y.max(region.max.y),
                    all.max.z.max(region.max.z),
                ),
            });

        Ok(Self {
            separation,
            islands,
            bounds,
        })
    }

    pub const fn separation(&self) -> u32 {
        self.separation
    }

    pub const fn config(&self, island: IslandId) -> IslandConfig {
        self.islands[island as usize]
    }

    /// The smallest box holding every island's region: exactly the global grid's extent.
    pub const fn bounds(&self) -> IslandBounds {
        self.bounds
    }

    /// The global grid's `(width, height, depth)`.
    pub fn grid_dimensions(&self) -> (usize, usize, usize) {
        let extent = |min: i32, max: i32| (i64::from(max) - i64::from(min) + 1) as usize;
        let IslandBounds { min, max } = self.bounds;
        (
            extent(min.x, max.x),
            extent(min.y, max.y),
            extent(min.z, max.z),
        )
    }
}

/// Applies `build` to every island in `IslandId::ALL` order, or returns the first error.
fn per_island<T: Copy>(
    build: impl FnMut(IslandId) -> Result<T, ArenaError>,
) -> Result<[T; 5], ArenaError> {
    let results = IslandId::ALL.map(build);
    if let Some(&Err(error)) = results.iter().find(|result| result.is_err()) {
        return Err(error);
    }
    Ok(results.map(|result| result.expect("errors were returned above")))
}

/// One island's config: the center 24×24 at the origin, each outer island 16×16 `separation`
/// blocks out along its axis, all at `SURFACE_LEVEL`.
fn island_config(id: IslandId, separation: u32) -> Result<IslandConfig, ArenaError> {
    let (dx, dz) = id.direction();
    let coordinate = |step: i32| {
        i32::try_from(i64::from(step) * i64::from(separation)).map_err(|_| ArenaError::Island {
            island: id,
            error: IslandError::CoordinateOverflow,
        })
    };
    let center = VoxelPosition::new(coordinate(dx)?, SURFACE_LEVEL, coordinate(dz)?);
    Ok(if id.is_center() {
        IslandConfig {
            center,
            footprint_width: CENTER_FOOTPRINT,
            footprint_depth: CENTER_FOOTPRINT,
            thickness: CENTER_THICKNESS,
        }
    } else {
        IslandConfig::new(center, OUTER_THICKNESS)
    })
}

/// Whether two inclusive regions overlap or leave fewer than `MIN_ISLAND_GAP` empty cells between
/// them on every axis.
fn too_close(a: IslandBounds, b: IslandBounds) -> bool {
    let gap = i64::from(MIN_ISLAND_GAP);
    let near = |a_min: i32, a_max: i32, b_min: i32, b_max: i32| {
        i64::from(a_min) <= i64::from(b_max) + gap && i64::from(b_min) <= i64::from(a_max) + gap
    };
    near(a.min.x, a.max.x, b.min.x, b.max.x)
        && near(a.min.y, a.max.y, b.min.y, b.max.y)
        && near(a.min.z, a.max.z, b.min.z, b.max.z)
}

/// What generation produced for one island.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ArenaIsland {
    pub id: IslandId,
    pub config: IslandConfig,
    /// The seed passed to `generate_island`, derived from the global seed.
    pub seed: u64,
    pub stats: IslandStats,
}

/// Arena metadata for logging and for placing later bridges and structures.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ArenaInfo {
    pub global_seed: u64,
    pub separation: u32,
    /// Indexed by `IslandId as usize`.
    pub islands: [ArenaIsland; 5],
    pub grid_origin: VoxelPosition,
    /// `(width, height, depth)` of the global grid.
    pub grid_dimensions: (usize, usize, usize),
    pub occupied_voxels: usize,
}

impl ArenaInfo {
    pub const fn island(&self, island: IslandId) -> &ArenaIsland {
        &self.islands[island as usize]
    }

    pub fn ores(&self) -> usize {
        self.islands.iter().map(|island| island.stats.ores()).sum()
    }

    pub fn count(&self, block: BlockType) -> usize {
        self.islands
            .iter()
            .map(|island| island.stats.count(block))
            .sum()
    }
}

/// The generated arena: the one global grid and its metadata.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Arena {
    pub grid: VoxelGrid,
    pub info: ArenaInfo,
}

/// Generates all five islands of `layout` for `global_seed` into one new grid sized exactly to
/// the layout's bounds.
///
/// The layout was validated when it was built, so the only failure left is creating the grid,
/// which happens before any island is written: an error never yields a partial arena.
pub fn generate_arena(layout: &ArenaLayout, global_seed: u64) -> Result<Arena, ArenaError> {
    generate_arena_in(layout, global_seed, layout.bounds)
}

/// Like `generate_arena`, but into a grid covering `bounds`, which must contain the layout's
/// bounds: the extra cells are empty room for construction. Islands never depend on the grid
/// around them, so the terrain is cell-for-cell the terrain `generate_arena` produces.
pub fn generate_arena_in(
    layout: &ArenaLayout,
    global_seed: u64,
    bounds: IslandBounds,
) -> Result<Arena, ArenaError> {
    let required = layout.bounds;
    if !bounds.contains(required.min) || !bounds.contains(required.max) {
        return Err(ArenaError::GridTooSmall);
    }
    let extent = |min: i32, max: i32| (i64::from(max) - i64::from(min) + 1) as usize;
    let (width, height, depth) = (
        extent(bounds.min.x, bounds.max.x),
        extent(bounds.min.y, bounds.max.y),
        extent(bounds.min.z, bounds.max.z),
    );
    let mut grid =
        VoxelGrid::try_new(bounds.min, width, height, depth).map_err(ArenaError::Grid)?;

    let islands = IslandId::ALL.map(|id| {
        let config = layout.config(id);
        let seed = island_seed(global_seed, id);
        let stats = generate_island(&mut grid, &config, seed)
            .expect("validated island regions lie inside the arena grid");
        ArenaIsland {
            id,
            config,
            seed,
            stats,
        }
    });
    let occupied_voxels = islands.iter().map(|island| island.stats.total()).sum();

    Ok(Arena {
        grid,
        info: ArenaInfo {
            global_seed,
            separation: layout.separation,
            islands,
            grid_origin: bounds.min,
            grid_dimensions: (width, height, depth),
            occupied_voxels,
        },
    })
}
